import json
import os
import sys
import tempfile


def main():
    if len(sys.argv) != 2:
        print("usage: probe.py <directory>", file=sys.stderr)
        return 1

    directory = sys.argv[1]

    costs = []
    for entry in sorted(os.listdir(directory)):
        if not entry.endswith(".json"):
            continue
        path = os.path.join(directory, entry)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r") as f:
                data = json.load(f)
        except (json.JSONDecodeError, OSError):
            continue
        if isinstance(data, dict) and "cost_usd" in data:
            costs.append(data["cost_usd"])

    total = sum(costs)
    mean = total / len(costs) if costs else 0

    summary = {"total": total, "mean": mean}

    out_dir = os.getcwd()
    fd, tmp_path = tempfile.mkstemp(dir=out_dir, prefix=".summary.json.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w") as f:
            json.dump(summary, f)
        os.replace(tmp_path, os.path.join(out_dir, "summary.json"))
    except BaseException:
        os.remove(tmp_path)
        raise

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
